(1, 1, 8, 'louren.rubico@frontlinebusiness.com.ph', 'Test ko ito', '<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>FBS Marketing Website Newsletter</title>\n    <!-- CSS -->\n    <style>\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n        /* outline: 1px solid red; */\n      }\n      body {\n        font-family: Arial, Helvetica, sans-serif !important;\n        color: #333;\n      }\n      .canvas {\n        width: 700px;\n        margin: 0 auto;\n        background-color: #f9f9f9;\n      }\n      table {\n        border-spacing: 0;\n      }\n      .welcomeMobile {\n        display: none;\n      }\n      .welcomeDesktop {\n        display: block;\n      }\n      .partnerMobile {\n        display: none;\n      }\n      .partnerDesktop {\n        display: block;\n      }\n      .renewalMobile {\n        display: none;\n      }\n      .renewalDesktop {\n        display: block;\n      }\n      .partnerMobile--block1 img,\n      .partnerMobile--block2 img,\n      .renewalMobile--block1 img {\n        width: 100% !important;\n      }\n      @media screen and (min-width: 340px) and (max-width: 520px) {\n        .canvas {\n          width: 100% !important;\n          background-color: #f9f9f9 !important;\n        }\n        .container {\n          width: 100% !important;\n          padding: 0 !important;\n          margin: 0 auto !important;\n        }\n        .newsLetter {\n          padding: 0 !important;\n        }\n        table {\n          width: 520px !important;\n        }\n        .title {\n          padding: 0 !important;\n          background-size: 100vw !important;\n          height: 127px !important;\n        }\n        .welcomeMobile {\n          display: block;\n        }\n        .welcomeDesktop {\n          display: none;\n        }\n        .partnerMobile {\n          display: block;\n        }\n        .partnerMobile--block2 {\n          margin-top: 70px;\n        }\n        .partnerDesktop {\n          display: none;\n        }\n        .renewalMobile {\n          display: block;\n        }\n        .renewalDesktop {\n          display: none;\n        }\n        .fellowship img {\n          width: 100% !important;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <section class=\"newsLetter\" style=\"background-color: white; padding: 0\">\n      <div\n        class=\"container\"\n        style=\"width: 700px; margin: 0 auto; background-color: white\"\n      >\n        <div class=\"canvas\">\n          <!-- TITLE -->\n          <div\n            class=\"title\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczOdZtJGJfu6DvsKfNErCpQjezh3fLHVMunDqwfWy4u1ExSkRcXh88-7V1X6SZkIkaKWRLj2Lac9thC6d7piVDPawLj384xlMm2nU3oO3t936Lzrd6g=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 205px;\n              border: none;\n            \"\n          ></div>\n          <!-- BACKGROUND IMAGE -->\n          <div\n            class=\"imageSeperator\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczOlbKgxTNTJPezw5X1Bs5_IGWvWP1N8Hzf0SEqnnTUdYg6xGzGXFffsG-TxSMvtcE7oEQjyi-APGKQD-iRrjAEGUFMBGB-xZfN5wXJtCuMO6BrL4Ks=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 350px;\n              border: none;\n            \"\n          ></div>\n          <!-- DESC -->\n          <div\n            class=\"desc\"\n            style=\"padding: 32px 17px 48px; background-color: #fff\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              Why Virtual Assistants Are the Secret Weapon <br />\n              for Business Success?\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Know the game-changer in running your business.\n            </small>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              Imagine waking up to an endless to-do list-emails, social media\n              updates, and admin tasks piling up. Sound familiar? As a business\n              owner, managing everything alone can be overwhelming. But what if\n              you didn\'t have to?\n            </p>\n            <p style=\"font-size: 14px\">\n              With Virtual Assistance Services, your business stays efficient\n              while you focus on what matters most.\n            </p>\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/insight/why-virtual-assistants-are-the-secret-weapon-for-business-success\"\n                style=\"\n                  color: #f2f2f2;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #6a1142, #d60070);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- WELCOME MESSAGE DESKTOP -->\n          <div\n            class=\"welcomeDesktop\"\n            style=\"padding: 32px 17px 48px; background-color: #fef7ed\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              Welcoming Our New Clients in Virtual <br />\n              Assistance & Social Media Management\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Virtual Assistant Solutions\n            </small>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              We\'re excited to welcome our newest clients who have entrusted us\n              with their Virtual Assistant and Social Media Management needs! At\n              Frontline Business Solutions, we\'re committed to helping\n              businesses streamline operations and enhance their online\n              presence.\n            </p>\n            <table\n              cellpadding=\"0\"\n              cellspacing=\"0\"\n              role=\"presentation\"\n              style=\"width: 650px; height: 0px; padding: 0\"\n            >\n              <tr>\n                <td class=\"logo\" style=\"vertical-align: top\" width=\"10%\">\n                  <a href=\"#\"\n                    ><img\n                      src=\"https://lh3.googleusercontent.com/pw/AP1GczNfTex3xE76-6CADK0b8cNVYsBsebvnarT6DIm-FSDjfu02i0cejzosawR6EkX11rWmPf67iUOsExL5uspYjKCmOSCZ7jtRrkY228W9U2qSVJIiS6k=w2400\"\n                      alt=\"\"\n                      style=\"width: 200px; margin-bottom: 16px; display: block\"\n                  /></a>\n                </td>\n                <td class=\"logo\" style=\"vertical-align: top\" width=\"10%\">\n                  <a href=\"#\"\n                    ><img\n                      src=\"https://lh3.googleusercontent.com/pw/AP1GczNoAEDCWerM_QYoXkQXxMHb4SBDNUrYZs-KQKBPitwaIYmdGwRjebcn83zL0C7XrcWqy4R0tKYJiAZ2t6nhrs01ia9N_ZrpuKI0WH4Kx-PeJAy4U_I=w2400\"\n                      alt=\"\"\n                      style=\"width: 200px; margin-bottom: 16px; display: block\"\n                  /></a>\n                </td>\n                <td class=\"logo\" style=\"v