n-bottom: 16px;\n              \"\n            >\n              We deliver end-to-end solutions and professional expertise in\n              <br />\n              web applications, websites, virtual assistants, and skills\n              development.\n            </p>\n            <div class=\"icons\" style=\"margin-bottom: 8px; text-align: center\">\n              <a\n                href=\"https://www.facebook.com/frontline.business\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczNEy4pqCkdZ3TI2U5_ty1rsyAr287bs1MKnE9is6Wfvg9JYCZ5AuEqQHD7jyKVINg7Oy2P6ntdVGi8qkzby1H4P2XlaoqSsrNkIQkQ9FyhWBea3x6E=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.linkedin.com/company/frontline-business-solutions-inc/\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPi3buvL5Un9DyKoGLP0zaolXrXyV7hP8M8IwAcvxWiaysuZxscVzw9hReEoP5j5xr1-F3Fx1JI32UEmV3pv949c33m1JbEedeUHbxh1JrcxkHxlP8=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.youtube.com/@frontlinebusinesssolutions6578\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczOFaymIU4G3nFFhSiWbsv-JRGDD31-RCXOyDulqVuIEldQDH-04FJBepWSVQRk0iTxi1Pf4hY_SoNIEEdoWBxmWXAwLX3ePScXnh-LM5846LaM6O8s=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.instagram.com/frontline.business/\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPPsABBWthmMwhMnRaz0NxOwLNe_F5dyau9JBbQUAbT48kN5S7WKa1_M6SSb6awE4kFyDiIKv7prYY2wCPNfYegju-Ph0xjM9khTrzBbAb0eY8AUwA=s70-p-k\"\n                  alt=\"\"\n              /></a>\n              <a\n                href=\"https://www.tiktok.com/@frontlinebusinessinc\"\n                style=\"display: inline-block\"\n                ><img\n                  style=\"width: 25px; height: 25px\"\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczNF50VT3hd-2PhvM_OUWALWmBgwrHp3drnQM-wGSSP5-C-RHXP-HePnxs4W-f8dDzun14Jth78npNTahLoR-9snETM5vsIPBBvdXzJfqPS8-eYZwiA=s70-p-k\"\n                  alt=\"\"\n              /></a>\n            </div>\n            <div style=\"text-align: center; line-height: 1\">\n              <p style=\"font-size: 16px; color: #fff\">\n                <small>\n                  Copyright 2025, All rights reserved. <br />\n                  Baloc Road, Brgy, San Ignacio, San Pablo City, Laguna\n                  Philippines 4000<br />\n                  <br />\n                  You are receiving this email because you opted in at our\n                  website. <br />\n                \n              </p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  </body>\n</html>', 1, '47e26eaffab557f0aea866fb313e311a713431a378080cf9210c02ddce4776e0', '2025-03-03 11:02:33', '0000-00-00 00:00:00');
