(13, 1, 8, 'louren.rubico@frontlinebusiness.com.ph', 'Test Newsletter April 2025', '<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <!--Dark Mode meta tags needed to enable Dark Mode in email client user agents-->\n    <meta name=\"color-scheme\" content=\"light dark\" />\n    <meta name=\"supported-color-schemes\" content=\"light dark only\" />\n\n    <title>FBS Marketing Website Newsletter</title>\n    <!-- CSS -->\n    <style>\n      :root {\n        color-scheme: light dark;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n        /* outline: 1px solid red; */\n      }\n      body {\n        font-family: Arial, Helvetica, sans-serif !important;\n        color: #333;\n      }\n      .canvas {\n        width: 700px;\n        margin: 0 auto;\n        background-color: #f9f9f9;\n      }\n      table {\n        border-spacing: 0;\n      }\n      .webAppServicesMobile {\n        display: none;\n      }\n      .webAppServicesDesktop {\n        display: block;\n      }\n      .renewalMobile {\n        display: none;\n      }\n      .renewalDesktop {\n        display: block;\n      }\n      .mobileSTI {\n        display: none;\n      }\n      .desktopSTI {\n        display: block;\n      }\n\n      @media screen and (min-width: 340px) and (max-width: 520px) {\n        .canvas {\n          width: 100% !important;\n          background-color: #f9f9f9 !important;\n        }\n        .container {\n          width: 100% !important;\n          padding: 0 !important;\n          margin: 0 auto !important;\n        }\n        .newsLetter {\n          padding: 0 !important;\n        }\n        table {\n          width: 520px !important;\n        }\n        .title {\n          padding: 0 !important;\n          background-size: 100vw !important;\n          height: 127px !important;\n        }\n\n        .webAppServicesMobile {\n          display: block;\n        }\n        .webAppServicesDesktop {\n          display: none;\n        }\n        .mobileSTI {\n          display: block;\n        }\n        .desktopSTI {\n          display: none;\n        }\n        .fellowship img {\n          width: 100% !important;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <section class=\"newsLetter\" style=\"background-color: white; padding: 0\">\n      <div\n        class=\"container\"\n        style=\"width: 700px; margin: 0 auto; background-color: white\"\n      >\n        <div class=\"canvas\">\n          <!-- TITLE -->\n          <div\n            class=\"title\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczOAvLKsqq_TE22a93RQy9yXbMgwIsZ23x3mAbrwGpT4La71pEdoDfx_fcXA4FW_uRz9obowug74lPE3Ze7uFbBjWEx7PgyOdXsv-0ryO2hdq51oH0U=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 205px;\n              border: none;\n            \"\n          ></div>\n          <!-- BACKGROUND IMAGE -->\n          <div\n            class=\"imageSeperator\"\n            style=\"\n              background-image: url(\'https://lh3.googleusercontent.com/pw/AP1GczMX9497z3Js-bzHX88v73QPvei5JzeL_oqbyJplK8oKg2FXriiFTeqh2TbnK_MT5o4SULLptc0XyfKr2PimhaMMNfo9GDuOpVH82qI5z3J6TeljIGA=w2400\');\n              background-repeat: no-repeat;\n              background-size: cover;\n              background-position: center;\n              height: 350px;\n              border: none;\n            \"\n          ></div>\n          <!-- DESC -->\n          <div\n            class=\"desc\"\n            style=\"padding: 48px 24px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              Transforming Business Operations with Customized Web Applications\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Web Applications and Web Services\n            </small>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              In today\'s digital-driven world, businesses need more than just a\n              website to stay competitive. Customized web applications provide\n              organizations with tailored solutions that streamline operations,\n              enhance efficiency, and improve user experience. At Frontline\n              Business Solutions, Inc., we go beyond website development by\n              delivering powerful web applications designed to meet the unique\n              needs of businesses across various industries.\n            </p>\n            <div class=\"webAppServicesDesktop\">\n              <table\n                cellpadding=\"0\"\n                cellspacing=\"0\"\n                role=\"presentation\"\n                style=\"\n                  width: 670px;\n                  height: 0px;\n                  padding-top: 32px;\n                  text-align: center;\n                \"\n              >\n                <tr>\n                  <td style=\"vertical-align: top\" width=\"50%\">\n                    <h4\n                      style=\"\n                        text-align: center;\n                        font-size: 14px;\n                        white-space: nowrap;\n                        color: #d60070;\n                        margin-bottom: 10px;\n                      \"\n                    >\n                      THE ADVANTAGES OF CUSTOMIZED <br />\n                      WEB APPLICATIONS\n                    </h4>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Tailored to Business Needs\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Scalability and Flexibility\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Improved Efficiency and Productivity\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Enhanced Security\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                     