ttom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      School Enrollment System.\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Online Payment Integration\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Online Donation System\n                    </div>\n                    <div style=\"vertical-align: bottom; text-align: left\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                        alt=\"\"\n                        style=\"width: 16px; margin-right: 10px\"\n                      />\n\n                      Asset Inventory System\n                    </div>\n                  </td>\n                </tr>\n              </table>\n            </div>\n            <div class=\"webAppServicesMobile\">\n              <div class=\"\" style=\"max-width: fit-content; margin: 30px auto\">\n                <h4\n                  style=\"\n                    text-align: center;\n                    font-size: 14px;\n                    white-space: nowrap;\n                    color: #d60070;\n                    margin-bottom: 10px;\n                  \"\n                >\n                  THE ADVANTAGES OF CUSTOMIZED <br />\n                  WEB APPLICATIONS\n                </h4>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Tailored to Business Needs\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Scalability and Flexibility\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Improved Efficiency and Productivity\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Enhanced Security\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczPKRBc-6gVACQXmYzcfxWGLMR9zzLy4LvcnjJ6a4uVWCd8qyinvBxU8gL_ibOCdbtXK4bmTPj8oAFCZ0BLV2UjB-jsp1JmyMwQt3yg9oAGlcK5sIso=s176-p-k\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Seamless Integration\n                </div>\n              </div>\n              <div class=\"\" style=\"max-width: fit-content; margin: 30px auto\">\n                <h4\n                  style=\"\n                    text-align: center;\n                    font-size: 14px;\n                    white-space: wrap;\n                    color: #d60070;\n                    margin-bottom: 10px;\n                  \"\n                >\n                  OUR WEB <br />\n                  APPLICATION SOLUTIONS\n                </h4>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  HR Information System (HRIS)\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Online Payroll System\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  School Enrollment System.\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Online Payment Integration\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Online Donation System\n                </div>\n                <div style=\"vertical-align: bottom; text-align: left\">\n                  <img\n                    src=\"https://lh3.googleusercontent.com/pw/AP1GczOAzFGklbHPzOWs0O7_GWTFtdCSW2DIe_2efo6Smjz35HYae1YVqaklVjFHlXDHLsBmc-FcwKvfRCbnlscljHelppCDRJ_N_ksuFYwD_QS5PHZFjdY=w2400\"\n                    alt=\"\"\n                    style=\"width: 16px; margin-right: 10px\"\n                  />\n\n                  Asset Inventory System\n                </div>\n              </div>\n            </div>\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/insight/transforming-business-operations-with-customized-web-applications\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- STI -->\n          <div\n            class=\"STI\"\n            style=\"padding: 48px 24px; background-color: #fef7ed\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              21 STI College San Pablo Students Complete Work Immersion in Web\n              Design & Frontend Development\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Learning Center Solutions Service\n            </small>\n\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              Frontline Business Solutions, Inc. proudly celebrates the\n              successful completion of 21 students from STI College San Pablo,\n              who recently finished their Senior High School Work Immersion\n              program. These students, taking the ICT (Information and\n              Communications Technology) strand, gained valuable industry\n              experience in Web Design and Frontend Development using Figma,\n              HTML, CSS, and JavaScript\n            </p>\n            <!-- desktop -->\n            <div class=\"desktopSTI\">\n              <table\n                cellpadding=\"0\"\n                cellspacing=\"0\"\n                role=\"presentation\"\n                style=\"\n                  width: 670px;\n                  height: 0px;\n                  padding-top: 32px;\n                  text-align: center;\n                \"\n              >\n                <tr>\n                  <td style=\"vertical-align: top\" width=\"50%\">\n                    <a href=\"#\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczM5de6lWQ0jfg1LabAgUvb6irNo4h0LhMxftI3w8dJ0X0_oY2T1Q1aI6qIJ7yEZtdCiA5FzukAdNhq79vGimI68mMZneD53ruMUA0xC9YARw2jDdp0=w2400\n\"\n                        alt=\"\"\n                        style=\"display: block; width: 317px\"\n                    /></a>\n                  </td>\n                  <td style=\"vertical-align: top\" width=\"50%\">\n                    <a href=\"#\">\n                      <img\n                        src=\"https://lh3.googleusercontent.com/pw/AP1GczPpffcSNGo-98lHNXZuNjCdgeQTsoRzAVbpZINUpNdTdIVE2EAFPguEudhcMkEifmr4KlrLOXNjpJt7KAnexR_8cccUtjqL7tKpr1bQlKagC4dWO5c=w2400\"\n                        alt=\"\"\n                        style=\"display: block; width: 317px\"\n                      />\n                    </a>\n                  </td>\n                </tr>\n              </table>\n            </div>\n            <!-- mobile -->\n            <div class=\"mobileSTI\">\n              <a href=\"#\">\n                <img\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczM5de6lWQ0jfg1LabAgUvb6irNo4h0LhMxftI3w8dJ0X0_oY2T1Q1aI6qIJ7yEZtdCiA5FzukAdNhq79vGimI68mMZneD53ruMUA0xC9YARw2jDdp0=w2400\n\"\n                  alt=\"\"\n                  style=\"display: block; width: 317px; margin: 20px auto\"\n              /></a>\n              <a href=\"#\">\n                <img\n                  src=\"https://lh3.googleusercontent.com/pw/AP1GczPpffcSNGo-98lHNXZuNjCdgeQTsoRzAVbpZINUpNdTdIVE2EAFPguEudhcMkEifmr4KlrLOXNjpJt7KAnexR_8cccUtjqL7tKpr1bQlKagC4dWO5c=w2400\"\n                  alt=\"\"\n                  style=\"display: block; width: 317px; margin: 20px auto\"\n                />\n              </a>\n            </div>\n\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/events-and-activities/21-STI-College-San-Pablo-Students-Work-Immersion-Completion\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n\n          <!-- FELLOWSHIP -->\n          <div\n            class=\"fellowship\"\n            style=\"padding: 48px 24px; background-color: #f2f2f2\"\n          >\n            <h2\n              style=\"\n                font-weight: 900;\n                font-size: 25.3px;\n                line-height: 30px;\n                margin-bottom: 1px;\n                margin-top: 0;\n              \"\n            >\n              Annual Team Building 2025\n            </h2>\n            <small style=\"font-size: 14px; font-weight: 600; color: #d60070\">\n              Company Culture and Team Building\n            </small>\n            <p style=\"font-size: 14px; margin: 20px 0\">\n              Frontline Business Solutions, Inc. recently held its highly\n              anticipated annual team-building event from April 28 to 30 at the\n              picturesque Sabangan Beach Resort in Laiya, San Juan, Batangas.\n              This year\'s theme, \"Raising the Bar, Reaching Far,\" encapsulated\n              the company\'s commitment to continuous growth, excellence, and\n              teamwork. Over three days, employees engaged in insightful\n              discussions, thrilling activities, and moments of reflection,\n              strengthening their bonds as one Frontline family.\n            </p>\n            <a href=\"#\">\n              <img\n                src=\"https://lh3.googleusercontent.com/pw/AP1GczNnIQ_0-Ph5xk9RqYb4e-shoArCQjwDFVTIXAvmpCqfm6FYeoLztrrLYg8c5606_MqJ6RgXJwXEVf26dnuUPREYa5w-48Ky-lBEDVKbPFSq0dIzKhs=w2400\"\n                alt=\"\"\n                style=\"\n                  width: 657px;\n                  display: block;\n                  margin-left: auto;\n                  margin-right: auto;\n                \"\n              />\n            </a>\n            <div style=\"text-align: center; margin-top: 26px\">\n              <a\n                class=\"btn\"\n                href=\"https://frontlinebusiness.com.ph/events-and-activities/raising-the-bar,%20reaching-far:%20fbs\'-team-building-2025\"\n                style=\"\n                  display: inline-block;\n                  color: #dbd5d5;\n                  font-weight: 300;\n                  padding: 12px 50px;\n                  background: linear-gradient(to right, #d60070, #6a1142);\n                  border-radius: 5px;\n                  text-decoration: none;\n                  font-size: 12px;\n                \"\n                >Read more</a\n              >\n            </div>\n          </div>\n          <!-- F